/* =====================================================================
   PART 14 · PRACTICE ARENA (engine + beginner & intermediate challenges)
   #/page/practice            → challenge list (filter by level / search)
   #/page/practice/<id>       → prompt → your notes → hint 1 → 2 → 3 →
                                 solution outline with an animated diagram
   Also defines SDA.miniDiagram: a compact grid layout used by practice
   solutions and project HLDs (nodes placed by column/row).
   ===================================================================== */
(function(){
const SDA = window.SDA; const {el, esc} = SDA.u; const ui = SDA.ui; const h = SDA.h; const Store = SDA.store;
const frag = html => document.createRange().createContextualFragment(html);

/* ---------- mini diagram DSL ----------
   n: [[id, type, label, sub, col, row, w?]]   col 0..4, row 0..2
   e: 'a>b c>d a>c~0.3'                         (~ = curve)
   f: [[note, 'a>b:label|b>c']]                 (animated steps)       */
const COLX = c => 70 + c * 185, ROWY = r => 50 + r * 115;
function miniSpec(spec){
  const nodes = spec.n.map(([id, type, label, sub, c, r, w]) => ({id, type, label, sub:sub || '', x:COLX(c), y:ROWY(r), w:w || (type === 'client' ? 110 : 134)}));
  const edges = spec.e.trim().split(/\s+/).map(s => { const [ab, cv] = s.split('~'); const [from, to] = ab.split('>'); return cv ? {from, to, curve:+cv} : {from, to}; });
  const steps = (spec.f || []).map(([note, hops]) => ({note, flow:hops.split('|').map(x => { const i = x.indexOf(':'); const ab = i >= 0 ? x.slice(0, i) : x, lab = i >= 0 ? x.slice(i + 1).trim() : null; const [a, b] = ab.split('>').map(s => s.trim()); return lab ? [a, b, lab] : [a, b]; })}));
  const W = Math.max(...nodes.map(n => n.x + n.w / 2)) + 16, H = Math.max(...nodes.map(n => n.y)) + 50;
  return {nodes, edges, steps, w:Math.max(560, W), h:Math.max(200, H)};
}
SDA.miniSpec = miniSpec;
SDA.miniDiagram = function(host, spec, title){ const s = miniSpec(spec); return new SDA.Diagram(host, {title, w:s.w, h:s.h, minW:560, alt:title, nodes:s.nodes, edges:s.edges, steps:s.steps, autoplay:false}); };

/* ---------- challenge registry ---------- */
SDA.challenges = SDA.challenges || new Map();
const LV = {beginner:{label:'Beginner', icon:'🌱'}, intermediate:{label:'Intermediate', icon:'🧱'}, advanced:{label:'Advanced', icon:'🚀'}};
SDA.addKind('challenge', c => { ['id', 'level', 'title', 'prompt', 'hints', 'solution'].forEach(k => { if (c[k] == null) throw new Error('challenge ' + (c.id || '?') + ' needs ' + k); }); if (c.hints.length !== 3) throw new Error('challenge ' + c.id + ' needs 3 hints'); SDA.challenges.set(c.id, c); });
SDA.searchProviders.push(() => [...SDA.challenges.values()].map(c => ({kind:'Practice', icon:c.icon || '🧩', title:c.title, sub:'Practice · ' + LV[c.level].label, href:'#/page/practice/' + c.id, kw:(c.tags || []).join(' ')})));
SDA.statProviders.push({label:'Practice challenges', count:() => SDA.challenges.size});
const notesKey = id => 'sda:practice-notes:' + id;
const getNotes = id => { try { return localStorage.getItem(notesKey(id)) || ''; } catch(e){ return ''; } };
const setNotes = (id, v) => { try { localStorage.setItem(notesKey(id), v); } catch(e){} };
const crumbs = list => el('nav', {class:'crumbs', 'aria-label':'Breadcrumb', html:list.map(([href, t]) => href ? `<a href="${href}">${esc(t)}</a>` : `<span aria-current="page">${esc(t)}</span>`).join('<span aria-hidden="true">/</span>')});

function renderList(ctx){
  const c = ctx.content; ctx.wide = true; let level = 'all', q = '', status = 'all';
  c.append(crumbs([['#/', 'Home'], [null, 'Practice Arena']]), el('h1', {class:'page-title'}, '🧩 Practice Arena'),
    el('p', {class:'lead'}, 'Design problems to solve on your own first. Write your approach, take hints one at a time, then compare with a full solution outline and diagram. Your notes stay in this browser.'));
  const all = [...SDA.challenges.values()];
  const solved = () => all.filter(x => Store.isDone('practice:' + x.id)).length;
  const prog = el('p', {class:'lab-hint'});
  const grid = el('div');
  const levelSel = ui.select({label:'Level', value:'all', options:[['all', 'All levels'], ['beginner', '🌱 Beginner'], ['intermediate', '🧱 Intermediate'], ['advanced', '🚀 Advanced']], onChange:v => { level = v; draw(); }});
  const statusSel = ui.select({label:'Status', value:'all', options:[['all', 'All'], ['todo', 'Not solved yet'], ['done', 'Solved']], onChange:v => { status = v; draw(); }});
  const search = el('input', {class:'input', type:'search', placeholder:'Filter by keyword…', 'aria-label':'Filter challenges'}); search.addEventListener('input', () => { q = search.value.toLowerCase(); draw(); });
  c.append(el('div', {class:'ctl-grid', style:{margin:'10px 0'}}, levelSel.el, statusSel.el, el('label', {class:'field'}, el('span', null, 'Search'), search)), prog, grid);
  function draw(){
    prog.textContent = `${solved()} of ${all.length} solved.`; grid.innerHTML = '';
    Object.keys(LV).forEach(lv => {
      if (level !== 'all' && level !== lv) return;
      const list = all.filter(x => x.level === lv && (!q || (x.title + ' ' + (x.tags || []).join(' ') + ' ' + SDA.u.stripHtml(x.prompt)).toLowerCase().includes(q)) && (status === 'all' || (status === 'done') === Store.isDone('practice:' + x.id)));
      if (!list.length) return;
      grid.append(el('div', {class:'sect-h'}, el('div', null, el('h2', null, `${LV[lv].icon} ${LV[lv].label}`), el('p', null, `${list.length} challenge${list.length > 1 ? 's' : ''}`))));
      const g = el('div', {class:'grid c3'});
      list.forEach(x => { const done = Store.isDone('practice:' + x.id); g.append(el('a', {class:'card glow', href:'#/page/practice/' + x.id}, el('div', {class:'row', style:{justifyContent:'space-between'}}, el('span', {class:'ico-lg', 'aria-hidden':'true'}, x.icon || '🧩'), done ? el('span', {class:'chip', style:{color:'var(--ok)'}}, '✓ solved') : el('span', {class:'chip'}, `${x.minutes || 30} min`)), el('b', {style:{display:'block', marginTop:'8px', color:'var(--text)', fontSize:'16px'}}, x.title), el('p', {class:'muted', style:{margin:'6px 0 0', fontSize:'14px'}}, x.tagline || ''))); });
      grid.append(g);
    });
    if (!grid.children.length) grid.append(el('div', {class:'empty'}, 'No challenges match these filters.'));
  }
  draw();
}

function renderOne(ctx, x){
  const c = ctx.content; ctx.title = x.title; ctx.track = {kind:'Practice', title:x.title, icon:x.icon || '🧩'};
  const all = [...SDA.challenges.values()]; const i = all.indexOf(x);
  c.append(crumbs([['#/', 'Home'], ['#/page/practice', 'Practice Arena'], [null, x.title]]));
  const doneB = ui.button(Store.isDone('practice:' + x.id) ? '✓ Solved' : 'Mark as solved', () => { const v = !Store.isDone('practice:' + x.id); Store.setDone('practice:' + x.id, v); doneB.innerHTML = v ? '✓ Solved' : 'Mark as solved'; }, 'sm');
  c.append(el('div', {class:'row', style:{marginTop:'12px', flexWrap:'wrap'}}, el('span', {class:'chip lvl'}, `${LV[x.level].icon} ${LV[x.level].label}`), el('span', {class:'chip'}, `⏱ ${x.minutes || 30} min`), ...(x.tags || []).map(t => el('span', {class:'chip'}, t)), doneB));
  c.append(el('h1', {class:'page-title'}, `${x.icon || '🧩'} ${x.title}`));
  c.append(el('div', {class:'prose'}, frag(`<p>${x.prompt}</p>` + (x.constraints && x.constraints.length ? `<h4>Constraints and numbers</h4>${h.list(x.constraints)}` : ''))));
  // notes
  const ta = el('textarea', {class:'input', rows:'6', style:{width:'100%', fontFamily:'var(--font-mono)', fontSize:'13px'}, placeholder:'Your approach: requirements, estimates, APIs, data model, components, bottlenecks… (saved in this browser)', 'aria-label':'Your notes'}); ta.value = getNotes(x.id); ta.addEventListener('input', () => setNotes(x.id, ta.value));
  c.append(el('h3', {style:{margin:'22px 0 8px'}}, '✍️ Your design first'), ta);
  // hints → solution
  const hintBox = el('div'); let shown = 0; const solBox = el('div');
  const hintB = ui.button('💡 Show hint 1', () => { if (shown >= 3) return; hintBox.append(el('div', {class:'callout info', style:{margin:'8px 0'}, html:`<b>Hint ${shown + 1}.</b> ${x.hints[shown]}`})); shown++; if (shown < 3) hintB.innerHTML = `💡 Show hint ${shown + 1}`; else { hintB.disabled = true; hintB.innerHTML = 'All hints shown'; solB.disabled = false; } }, 'sm');
  const solB = ui.button('📐 Show the solution outline', () => { solB.disabled = true; renderSolution(solBox, x); }, 'sm primary'); solB.disabled = true;
  const skip = el('button', {type:'button', class:'btn sm ghost'}, 'Skip to solution');
  skip.addEventListener('click', () => { if (solBox.childNodes.length) return; while (shown < 3) hintB.click(); solB.click(); });
  c.append(el('h3', {style:{margin:'22px 0 8px'}}, '🪜 Hints (one at a time)'), el('div', {class:'pill-row'}, hintB, solB, skip), hintBox, solBox);
  // prev / next
  const prev = all[i - 1], next = all[i + 1];
  c.append(el('div', {class:'row', style:{justifyContent:'space-between', marginTop:'28px', flexWrap:'wrap', gap:'8px'}}, prev ? el('a', {class:'btn sm ghost', href:'#/page/practice/' + prev.id}, '← ' + prev.title) : el('span'), next ? el('a', {class:'btn sm', href:'#/page/practice/' + next.id}, next.title + ' →') : el('span')));
}
function renderSolution(box, x){
  const s = x.solution;
  box.append(el('h3', {style:{margin:'22px 0 8px'}}, '📐 Solution outline'));
  if (s.summary) box.append(el('div', {class:'prose'}, frag(`<p>${s.summary}</p>`)));
  if (s.diagram){ const d = el('div'); box.append(d); SDA.miniDiagram(d, s.diagram, x.title + ': reference design'); }
  const g = el('div', {class:'grid c2'});
  (s.points || []).forEach(([hd, body]) => g.append(el('div', {class:'card'}, el('b', null, hd), el('div', {class:'prose', style:{marginTop:'6px'}}, frag(body)))));
  box.append(g);
  if (s.tradeoffs && s.tradeoffs.length) box.append(el('div', {class:'prose'}, frag('<h4>Trade-offs to mention</h4>' + h.table(['Decision', 'Why', 'What you give up'], s.tradeoffs, []))));
  const refs = (x.refs || []).map(r => SDA.resolve(r)).filter(Boolean);
  if (refs.length) box.append(el('h4', {style:{margin:'18px 0 8px'}}, '📚 Go deeper'), el('div', {class:'pill-row'}, ...refs.map(r => el('a', {class:'chip', href:r.href}, `${r.icon || ''} ${r.title}`))));
}
SDA.register({kind:'page', id:'practice', icon:'🧩', title:'Practice Arena', summary:'Design challenges with hints and solution outlines',
  render(ctx){ const x = ctx.args[0] && SDA.challenges.get(ctx.args[0]); if (ctx.args[0] && !x){ ctx.content.append(el('div', {class:'empty'}, 'Challenge not found. ', el('a', {href:'#/page/practice'}, 'All challenges →'))); return; } x ? renderOne(ctx, x) : renderList(ctx); }});
SDA.register({kind:'nav', label:'Practice Arena', href:'#/page/practice', icon:'🧩', order:4, group:'explore', desc:'Design challenges with hints 1→2→3 and solutions', count:() => SDA.challenges.size});

/* =========================== BEGINNER =========================== */
const C = def => SDA.register(Object.assign({kind:'challenge'}, def));
C({id:'page-views', level:'beginner', icon:'👀', minutes:25, title:'Page-view counter for a blog', tagline:'Count every view without melting the database.', tags:['counters', 'batching', 'caching'],
  prompt:'A popular blog wants a “👀 12,431 views” badge on every post, updated in near real time. Some posts go viral and get thousands of views per second. Design the counter.',
  constraints:['10M page views per day overall; a viral post can get 5,000 views/s', 'The number shown may lag by a few seconds', 'Counts must never go backwards or be lost on a restart', 'One relational database exists already'],
  hints:['What happens if every view runs <code>UPDATE posts SET views = views + 1</code> on the same row?', 'You don’t need every increment to hit the database: where could you add them up first?', 'Aggregate in memory (or in Redis with INCR), flush the totals to the database every few seconds, and serve the badge from the cache.'],
  solution:{summary:'Separate counting from storing. Increments go to a fast in-memory counter (Redis INCR, sharded by post); a flusher writes accumulated deltas to the database every few seconds; the badge reads the cache.',
    diagram:{n:[['u', 'client', 'Reader', '', 0, 1], ['app', 'service', 'Blog server', '', 1, 1], ['redis', 'cache', 'Redis', 'INCR views:{post}', 2, 0], ['flush', 'service', 'Flusher', 'every 5 s', 3, 0], ['db', 'db', 'Posts DB', 'views column', 3, 2]], e:'u>app app>redis redis>flush flush>db app>db', f:[['A view increments a counter in Redis: one tiny atomic operation.', 'u>app:GET /post/42|app>redis:INCR'], ['Every few seconds the flusher adds the accumulated delta to the database.', 'redis>flush:GETSET delta|flush>db:views += 3,812']]},
    points:[['1 · Requirements', '<p>Approximate, near-real-time display; durable eventual totals; spiky per-post load.</p>'], ['2 · Estimate', '<p>10M/day ≈ 115/s average, but one hot row can see 5K/s, which is the real problem: row-lock contention, not total volume.</p>'], ['3 · Data', '<p><code>posts.views BIGINT</code> as the durable total; <code>views:{post}</code> counter in Redis; a <code>views:dirty</code> set of posts with pending deltas.</p>'], ['4 · Deep dive', '<p>Use <code>GETSET</code>/<code>GETDEL</code> or a Lua script so a flush reads and resets the delta atomically; if the flush fails, add the delta back. If Redis restarts, at most a few seconds of views are lost (acceptable here; use AOF if not).</p>'], ['5 · Unique views?', '<p>Counting unique readers needs dedupe: a HyperLogLog per post (PFADD) gives ~1% error in 12 KB.</p>'], ['6 · Bottlenecks', '<p>A single Redis key for a mega-viral post is still one CPU core; shard it into N sub-counters and sum on read.</p>']],
    tradeoffs:[['Buffer in Redis', 'Removes hot-row contention', 'Seconds of loss risk on crash'], ['Approximate uniques (HLL)', 'Tiny memory', '~1% error']]},
  refs:['l:hll-cms', 'l:cache-strategies', 'l:locking']});
C({id:'qr-menu', level:'beginner', icon:'📱', minutes:25, title:'QR-code menus for 50,000 restaurants', tagline:'Mostly static, sometimes edited, read at lunchtime by everyone.', tags:['cdn', 'cache invalidation', 'static'],
  prompt:'Restaurants print a QR code on each table; scanning it opens their menu. Owners edit prices and mark dishes sold out from a dashboard. Design the system so menus load instantly on bad 4G.',
  constraints:['50K restaurants, ~200 dishes each, with photos', 'Lunch peak: 20K menu opens per second', 'A “sold out” change should show within a minute', 'Very small team: keep it simple'],
  hints:['How often does a menu change compared with how often it is read?', 'Could the menu be a static file instead of a database query on every scan?', 'Pre-render each menu to JSON/HTML on edit, push it to object storage + CDN, and invalidate (or version) that one file when the owner changes something.'],
  solution:{summary:'Read-heavy, write-rarely: generate each menu as a static artifact on every edit and serve it from a CDN. The QR code points at a stable URL; the CDN caches it with a short TTL or explicit invalidation.',
    diagram:{n:[['diner', 'client', 'Diner phone', '', 0, 0], ['owner', 'client', 'Owner', 'dashboard', 0, 2], ['cdn', 'cdn', 'CDN', 'menu files', 1, 0], ['api', 'service', 'Menu API', 'edits', 1, 2], ['db', 'db', 'Menus DB', '', 2, 2], ['build', 'service', 'Renderer', 'JSON + HTML', 3, 1], ['s3', 'db', 'Object storage', 'menu/{id}.json', 3, 0]], e:'diner>cdn cdn>s3 owner>api api>db api>build build>s3', f:[['A scan loads the menu file from the nearest CDN edge.', 'diner>cdn:GET /m/7781'], ['An edit updates the DB and re-renders that restaurant’s file, then invalidates the CDN path.', 'owner>api:dal makhani sold out|api>db|api>build|build>s3:new menu file']]},
    points:[['Estimate', '<p>20K opens/s × ~200 KB (with thumbnails) ≈ 4 GB/s: only a CDN makes sense. Edits are a few per second at most.</p>'], ['Data', '<p><code>restaurants</code>, <code>dishes(id, restaurant_id, name, price, available, photo_key)</code>; rendered file versioned by an edit counter.</p>'], ['Freshness', '<p>Either a short CDN TTL (60 s) or invalidate the path on edit; images use content-hashed URLs so they cache forever.</p>'], ['Failure', '<p>If the API is down, menus still load from the CDN; only edits wait.</p>'], ['Extras', '<p>Ordering from the table is a different, write-heavy flow: keep it separate from menu reads.</p>']],
    tradeoffs:[['Static files on a CDN', 'Fast, cheap, survives backend outages', 'Edits propagate with a small delay'], ['Short TTL vs invalidation', 'TTL is simplest', 'Up to TTL seconds of staleness']]},
  refs:['l:cdn', 'l:cache-invalidation']});
C({id:'thumbnails', level:'beginner', icon:'🖼️', minutes:30, title:'Image thumbnail service', tagline:'Upload once, resize in the background, serve fast.', tags:['async jobs', 'object storage', 'cdn', 'queues'],
  prompt:'Users of a marketplace app upload product photos (up to 20 MB). The app needs 4 sizes (thumbnail to full screen) in WebP and JPEG. Uploads should return quickly; thumbnails should appear within seconds.',
  constraints:['2M uploads per day, peaks of 200/s', 'Resizing takes ~1 s of CPU per image', 'Images are never edited, only deleted', 'Must handle duplicate uploads and corrupt files'],
  hints:['Should the upload request wait for resizing to finish?', 'Where should the original bytes go, and how does the app learn when sizes are ready?', 'Upload straight to object storage with a pre-signed URL, put a job on a queue, let a worker pool resize, and serve all sizes via CDN; retry failed jobs and send poison ones to a dead-letter queue.'],
  solution:{summary:'Decouple upload from processing. Clients upload the original directly to object storage (pre-signed URL), an event or queue message triggers workers that produce the sizes, and a CDN serves them by content-addressed URL.',
    diagram:{n:[['app', 'client', 'Seller app', '', 0, 1], ['api', 'service', 'Upload API', 'pre-signed URLs', 1, 1], ['s3', 'db', 'Object storage', 'originals + sizes', 2, 0], ['q', 'queue', 'Resize jobs', '+ DLQ', 2, 2], ['w', 'service', 'Workers', 'autoscaled', 3, 2], ['db', 'db', 'Images DB', 'status', 3, 1], ['cdn', 'cdn', 'CDN', '', 3, 0]], e:'app>api app>s3~-0.25 api>q q>w w>s3 w>db cdn>s3 api>db', f:[['The app gets a pre-signed URL and uploads directly to storage; the API never touches the bytes.', 'app>api:POST /uploads|app>s3:PUT original'], ['A job is queued; a worker resizes and writes four sizes, then marks the image ready.', 'api>q:resize 9f2c|q>w|w>s3:4 sizes|w>db:READY'], ['Buyers load sizes from the CDN.', 'cdn>s3:miss → size']]},
    points:[['Estimate', '<p>200 uploads/s × 1 s CPU ≈ 200 cores at peak; average 23/s ≈ 25 cores. Autoscale workers on queue depth.</p>'], ['Idempotency', '<p>Key outputs by the original’s SHA-256: re-processing a duplicate or a retried job overwrites the same objects.</p>'], ['Failures', '<p>Retry with backoff; after N failures move the job to a dead-letter queue and mark the image FAILED (corrupt file).</p>'], ['Serving', '<p><code>/img/{hash}/w640.webp</code> is immutable: cache forever; content negotiation picks WebP or JPEG.</p>'], ['Security', '<p>Validate type and size, strip EXIF location, scan for malware before publishing.</p>']],
    tradeoffs:[['Pre-signed direct upload', 'API servers stay light', 'Must validate after the fact'], ['Eager 4 sizes', 'Fast first view', 'Storage for sizes never viewed (vs on-the-fly resizing)']]},
  refs:['l:queues-pubsub-streams', 'l:ordering-dlq', 'l:transcoding-pipeline']});
C({id:'quiz-leaderboard', level:'beginner', icon:'🏆', minutes:25, title:'Live leaderboard for a quiz app', tagline:'Top 100 and “your rank” for a million players.', tags:['redis', 'sorted sets', 'ranking'],
  prompt:'A quiz app runs a 20-minute live contest every evening with up to 1M players. After each question, players see the top 100 and their own rank. Design the leaderboard.',
  constraints:['1M players, scores update after each of 20 questions', 'Rank lookups for every player after each question: ~1M reads in a few seconds', 'Ties: earlier answer ranks higher', 'Final results must be stored permanently'],
  hints:['Sorting a million rows in SQL after every question is too slow. Which data structure keeps items ordered as they change?', 'A Redis sorted set gives O(log n) updates and rank queries. How do you break ties by time?', 'Encode score and answer time into one sortable number (score × 10⁹ − elapsed ms), use ZINCRBY/ZADD and ZREVRANK; cache the top 100 for a second; persist results at the end.'],
  solution:{summary:'Keep the live board in a Redis sorted set keyed by contest: updates and rank queries are O(log n). Encode ties into the score. Serve the top 100 from a 1-second cache and write final results to the database after the contest.',
    diagram:{n:[['p', 'client', 'Player', '', 0, 1], ['api', 'service', 'Quiz API', '', 1, 1], ['z', 'cache', 'Redis ZSET', 'board:{contest}', 2, 0], ['top', 'cache', 'Top-100 cache', '1 s', 2, 2], ['db', 'db', 'Results DB', 'after contest', 3, 1]], e:'p>api api>z api>top top>z api>db', f:[['An answer updates the player’s score in the sorted set.', 'p>api:answer Q7|api>z:ZADD composite score'], ['Players read their rank and the cached top 100.', 'api>z:ZREVRANK|api>top:top 100'], ['At the end, the final board is written permanently.', 'api>db:bulk insert results']]},
    points:[['Estimate', '<p>1M updates per question spread over ~10 s = 100K ops/s: a single Redis node handles this; shard by contest if many run at once.</p>'], ['Ties', '<p>score_composite = points × 10⁹ + (10⁹ − ms_elapsed) so equal points sort by speed.</p>'], ['Reads', '<p>Top 100 is the same for everyone: compute once per second (ZREVRANGE 0 99) and cache; “my rank” is ZREVRANK per user.</p>'], ['Durability', '<p>Redis is the live view; answers are also logged so the board can be rebuilt if Redis fails.</p>']],
    tradeoffs:[['Redis sorted set', 'O(log n) rank and update', 'In-memory; must persist separately'], ['Cached top 100', 'Massive read reduction', 'Up to 1 s stale']]},
  refs:['l:redis-vs-memcached', 'l:cache-strategies']});
C({id:'otp-login', level:'beginner', icon:'🔐', minutes:25, title:'OTP login service', tagline:'Six digits, five minutes, and no SMS bombing.', tags:['security', 'ttl', 'rate limiting', 'failover'],
  prompt:'An app logs users in with a 6-digit OTP sent by SMS. Design the OTP service: generation, delivery, verification and abuse protection.',
  constraints:['50 logins/s at peak, 300/s during sales', 'OTP valid for 5 minutes, at most 5 attempts', 'SMS providers occasionally fail or slow down', 'Attackers try SMS bombing and brute force'],
  hints:['Where would you store the OTP so it expires on its own, and in what form?', 'What limits stop someone from sending 1,000 SMS to one number or guessing all 10⁶ codes?', 'Store a hash of the OTP with a 5-minute TTL plus an attempts counter; rate-limit sends per phone and per IP; deliver through a queue with provider failover; compare in constant time.'],
  solution:{summary:'Generate a random code, store only its hash with a TTL and attempt counter, send via a queue that fails over between SMS providers, and enforce rate limits on sends and verifications.',
    diagram:{n:[['u', 'client', 'User app', '', 0, 1], ['api', 'service', 'Auth API', '', 1, 1], ['redis', 'cache', 'Redis', 'otp hash · TTL 300 s', 2, 0], ['rl', 'cache', 'Rate limits', 'per phone / IP', 2, 2], ['q', 'queue', 'SMS queue', '', 3, 1], ['sms', 'ext', 'SMS providers', 'primary + backup', 4, 1]], e:'u>api api>redis api>rl api>q q>sms', f:[['Request a code: check send limits, store the hash with a TTL, queue the SMS.', 'u>api:POST /otp|api>rl:3 per 10 min|api>redis:SET hash EX 300|api>q|q>sms'], ['Verify: compare hashes, count attempts, delete on success.', 'u>api:POST /verify 482913|api>redis:check + INCR attempts']]},
    points:[['Generation', '<p>Use a cryptographic RNG; store <code>sha256(code + per-request salt)</code>, never the code.</p>'], ['Limits', '<p>Sends: e.g. 3 per 10 minutes per phone and per device, plus per-IP limits; verifications: 5 attempts then invalidate.</p>'], ['Delivery', '<p>Queue with a 2–3 s timeout per provider and failover to a backup provider; track delivery receipts per provider to route around failing ones.</p>'], ['User-visible latency', '<p>Total time = queue wait + provider time; show “resend in 30 s” rather than encouraging rapid retries.</p>'], ['Security', '<p>Constant-time comparison; bind the OTP to the login attempt (request id) so it can’t be replayed elsewhere.</p>']],
    tradeoffs:[['SMS OTP', 'Works for everyone with a phone', 'SIM-swap and phishing risk vs app-based or passkeys'], ['Strict rate limits', 'Stops bombing and brute force', 'Occasional friction for real users']]},
  refs:['l:rate-limiting', 'l:password-hashing', 'l:timeouts-retries', 'case:notification-service']});
C({id:'uptime-monitor', level:'beginner', icon:'🟢', minutes:30, title:'Uptime monitor and status page', tagline:'Check 100K URLs every minute and alert when they go down.', tags:['scheduling', 'workers', 'alerting'],
  prompt:'Build a service like a simple uptime checker: customers add URLs, the system checks each one every minute from several regions, alerts on failures, and shows a public status page.',
  constraints:['100K monitored URLs, 1-minute interval, 3 regions', 'A site is “down” only if 2 of 3 regions agree', 'Alerts by email and webhook within 2 minutes', 'Status pages get traffic spikes during outages'],
  hints:['How many checks per second is that, and how do you spread them evenly instead of all at :00?', 'How do you avoid paging a customer because one region had a network blip?', 'Shard URLs across scheduler workers by hash, jitter their offsets, write results to a time-series store, evaluate a 2-of-3 rule per URL, and serve status pages statically from a CDN.'],
  solution:{summary:'Partition URLs across checker workers in each region with spread-out schedules; collect results centrally; an evaluator applies a quorum rule and debounce before alerting; status pages are cached at the edge.',
    diagram:{n:[['cust', 'client', 'Customer', '', 0, 1], ['api', 'service', 'Config API', '', 1, 1], ['db', 'db', 'Monitors DB', '', 1, 2], ['chk', 'service', 'Checkers ×3 regions', 'sharded by hash', 2, 0], ['ts', 'db', 'Results', 'time series', 3, 0], ['eval', 'service', 'Evaluator', '2-of-3 rule', 3, 1], ['notif', 'ext', 'Email / webhooks', '', 4, 1], ['cdn', 'cdn', 'Status pages', 'CDN', 2, 2]], e:'cust>api api>db chk>db chk>ts ts>eval eval>notif eval>cdn', f:[['Checkers in three regions probe their share of URLs each minute and record results.', 'chk>db:my shard|chk>ts:latency, status'], ['The evaluator sees 2 of 3 regions failing for 2 checks in a row and alerts.', 'ts>eval|eval>notif:DOWN api.example.com'], ['The status page is regenerated and served from the CDN.', 'eval>cdn:incident page']]},
    points:[['Estimate', '<p>100K × 3 regions ÷ 60 s = 5K checks/s; with 2 s average check time ≈ 10K concurrent requests: async I/O workers, a few hundred per region.</p>'], ['Scheduling', '<p>Each URL gets offset = hash(id) mod 60 s, so load is flat; workers own shards via consistent hashing and rebalance when one dies.</p>'], ['False positives', '<p>Require 2 of 3 regions and 2 consecutive failures; alert on recovery too, with a short cool-down.</p>'], ['Storage', '<p>Raw results kept 7 days, rolled up to per-hour uptime for months.</p>']],
    tradeoffs:[['Quorum across regions', 'Few false alarms', 'Slightly slower detection'], ['Static status pages', 'Survive outage traffic spikes', 'Updates every ~30 s, not instantly']]},
  refs:['l:alerting-oncall', 'l:time-series', 'l:consistent-hashing']});
C({id:'static-hosting', level:'beginner', icon:'🌐', minutes:25, title:'Static website hosting', tagline:'Deploy with git push; serve millions from the edge.', tags:['cdn', 'deployments', 'immutable assets'],
  prompt:'Design a service like a simple static-site host: users push a folder of HTML/CSS/JS; it is served on their domain with HTTPS worldwide. Deploys must be atomic and roll back instantly.',
  constraints:['1M sites, most tiny; a few get millions of visits', 'Deploys must never serve a mix of old and new files', 'Instant rollback to any previous deploy', 'Free TLS certificates for custom domains'],
  hints:['If you overwrite files in place, what does a visitor see halfway through a deploy?', 'What if every deploy got its own immutable folder, and the domain pointed at one of them?', 'Upload each deploy to a new content-addressed prefix, then atomically switch a pointer (domain → deploy id) in a key-value store that edges read; rollback = switch the pointer back.'],
  solution:{summary:'Every deploy is immutable and stored under its own id; the live site is a pointer from hostname to deploy id. Edges resolve the pointer (cached briefly) and serve files from storage, with long-lived caching for hashed assets.',
    diagram:{n:[['dev', 'client', 'Developer', 'git push', 0, 0], ['v', 'client', 'Visitor', '', 0, 2], ['build', 'service', 'Deploy API', 'uploads files', 1, 0], ['s3', 'db', 'Object storage', 'deploys/{id}/…', 2, 0], ['kv', 'cache', 'Routing KV', 'host → deploy', 2, 1], ['edge', 'cdn', 'Edge servers', 'TLS + cache', 1, 2], ['acme', 'ext', 'Let’s Encrypt', 'certificates', 3, 2]], e:'dev>build build>s3 build>kv v>edge edge>kv edge>s3~-0.1 edge>acme~0.1', f:[['A deploy uploads every file to a new immutable prefix, then flips the pointer.', 'dev>build:push|build>s3:deploys/d812/|build>kv:site → d812'], ['A visitor’s request resolves the hostname and serves files from that deploy.', 'v>edge:GET /|edge>kv:site → d812|edge>s3:index.html']]},
    points:[['Atomic deploys', '<p>Readers see either the old pointer or the new one, never a mix of files.</p>'], ['Caching', '<p>Hashed assets (<code>app.3f9c.js</code>) cache forever; HTML caches briefly or is purged on deploy.</p>'], ['Domains and TLS', '<p>Verify domain ownership, then obtain certificates via ACME and store them for edges to load by SNI.</p>'], ['Dedupe', '<p>Store files by content hash so unchanged files across deploys aren’t uploaded twice.</p>']],
    tradeoffs:[['Immutable deploys + pointer', 'Atomic switch, instant rollback', 'Storage for old deploys (garbage-collect old ones)'], ['Edge pointer cache', 'Fast lookups', 'A few seconds before a new deploy is visible everywhere']]},
  refs:['l:cdn', 'l:deploy-strategies', 'l:https-tls']});
C({id:'news-comments', level:'beginner', icon:'💬', minutes:30, title:'Comments for a news site', tagline:'Threads, pagination, moderation, and an election-night spike.', tags:['pagination', 'moderation', 'caching', 'queues'],
  prompt:'A news site adds comments under every article: replies, likes, “newest/top” sorting, and moderation for abuse. On big news days one article can get 50,000 comments.',
  constraints:['5M comments per day; peaks of 500 writes/s on one article', 'Reads are 50× writes', 'Abusive comments should be hidden within seconds', 'Pages load the first 20 comments; more on scroll'],
  hints:['How would you paginate 50,000 comments without OFFSET 49,980?', 'Should moderation happen before or after a comment is visible, and synchronously?', 'Cursor (keyset) pagination on (article_id, created_at, id); cache the first page per article for a few seconds; publish new comments to a moderation queue (fast ML filter inline, human review async).'],
  solution:{summary:'Store comments keyed by article, paginate with cursors, cache the hot first page, and run moderation as a pipeline: a quick automated check before publishing and asynchronous review that can hide comments later.',
    diagram:{n:[['r', 'client', 'Reader', '', 0, 1], ['api', 'service', 'Comments API', '', 1, 1], ['cache', 'cache', 'First-page cache', '5 s', 2, 0], ['db', 'db', 'Comments DB', 'by article', 2, 2], ['q', 'queue', 'Moderation queue', '', 3, 1], ['mod', 'service', 'Moderation', 'ML + humans', 4, 1]], e:'r>api api>cache api>db api>q q>mod mod>db~-0.3', f:[['A new comment passes a quick filter, is stored and queued for review.', 'r>api:POST comment|api>db:INSERT|api>q:review'], ['Readers get the cached first page; scrolling uses a cursor.', 'r>api:GET ?cursor=…|api>cache:page 1|api>db:WHERE (created_at, id) < cursor']]},
    points:[['Data', '<p><code>comments(id, article_id, parent_id, author_id, body, status, created_at, likes)</code> with an index on (article_id, created_at DESC, id).</p>'], ['Threads', '<p>Store <code>parent_id</code>; load top-level comments by cursor and the first few replies per comment; “load more replies” fetches by parent.</p>'], ['Top sorting', '<p>Precompute a score (likes with time decay) periodically; avoid sorting 50K rows per request.</p>'], ['Spikes', '<p>Writes on one article are fine for a database; reads are absorbed by the first-page cache.</p>']],
    tradeoffs:[['Publish then review', 'Comments appear instantly', 'Abuse visible for seconds'], ['Cursor pagination', 'Constant-time deep pages', 'No jumping to page 500']]},
  refs:['l:indexes', 'l:queues-pubsub-streams', 'l:api-design']});
C({id:'weather-cache', level:'beginner', icon:'⛅', minutes:20, title:'Caching a rate-limited weather API', tagline:'Your provider allows 1,000 calls a day; your users want weather now.', tags:['caching', 'stale-while-revalidate', 'rate limits'],
  prompt:'Your app shows current weather for the user’s city. The paid weather provider allows only 1,000 requests per day and responds slowly (800 ms). You have 2M daily users across 300 cities.',
  constraints:['1,000 provider calls per day, hard limit', '300 cities; weather may be up to 15 minutes old', 'Provider sometimes fails for an hour', 'Users should never wait 800 ms'],
  hints:['How many distinct things do you actually need to fetch, and how often?', '300 cities × every 15 minutes is how many calls a day? Does that fit?', 'Cache per city with stale-while-revalidate; refresh popular cities on a schedule within the budget (e.g. top 100 every 30 min = 4,800 calls: too many, so prioritise and use bulk endpoints); serve stale data if the provider is down.'],
  solution:{summary:'The key is the call budget: key the cache by city (not user), refresh in the background on a budgeted schedule, and always answer from cache, serving stale data during provider outages.',
    diagram:{n:[['u', 'client', 'App', '', 0, 1], ['api', 'service', 'Weather API', 'ours', 1, 1], ['cache', 'cache', 'Cache', 'city → weather', 2, 1], ['sched', 'service', 'Refresher', 'budgeted', 3, 0], ['prov', 'ext', 'Provider', '1,000/day', 4, 1]], e:'u>api api>cache sched>cache sched>prov', f:[['Users always read from the cache, never the provider.', 'u>api:GET /weather?city=Pune|api>cache'], ['A refresher spends the daily budget on the cities that matter most.', 'sched>prov:bulk: 20 cities|sched>cache:update']]},
    points:[['Budget math', '<p>1,000 calls ÷ 24 h ≈ 42/h. 300 cities every 15 min would need 28,800 calls/day, so prioritise: top 40 cities hourly (960 calls), others when requested and older than 3 h, or use a bulk endpoint if available.</p>'], ['Stale-while-revalidate', '<p>Return the cached value immediately; if it’s old, trigger a background refresh (deduplicated per city).</p>'], ['Outages', '<p>Keep last-known data and show “updated 2 h ago” rather than failing.</p>'], ['Cost alternative', '<p>Compare a higher plan’s price with engineering effort; sometimes buying more quota is the right design.</p>']],
    tradeoffs:[['City-level cache', 'Budget-friendly', 'No per-street precision'], ['Serve stale', 'Always fast and available', 'Old data during outages']]},
  refs:['l:cache-strategies', 'l:cache-failure-modes', 'l:rate-limiting']});
C({id:'feature-flags', level:'beginner', icon:'🚩', minutes:30, title:'Feature-flag service', tagline:'Turn features on for 5% of users without a deploy.', tags:['configuration', 'push', 'local evaluation'],
  prompt:'Engineers want to turn features on and off at runtime, roll them out to a percentage of users, and kill a bad feature in seconds. 300 services, each handling thousands of requests per second, must check flags.',
  constraints:['300 services, 50K flag checks per second per service', 'A kill switch must take effect within 10 seconds', 'Flag checks must add no network latency', 'Percentage rollouts must be sticky per user'],
  hints:['Can each flag check be a network call to the flag service? Multiply it out.', 'What if services kept all flag rules in memory and evaluated them locally?', 'SDKs download the full ruleset, subscribe to changes (streaming or 5 s polling), evaluate locally, and bucket users by hash(flag, user_id) mod 100 for sticky percentages.'],
  solution:{summary:'Flags are evaluated in-process from a local copy of the rules; the flag service only distributes rule changes. Sticky rollouts use a deterministic hash of flag and user.',
    diagram:{n:[['eng', 'client', 'Engineer', 'dashboard', 0, 1], ['api', 'service', 'Flag API', '', 1, 1], ['db', 'db', 'Flags DB', 'rules + audit', 1, 2], ['stream', 'queue', 'Change stream', 'SSE / pub-sub', 2, 1], ['svc', 'service', 'Service + SDK', 'local rules', 3, 1], ['cdn', 'cdn', 'Rules snapshot', 'CDN', 2, 0]], e:'eng>api api>db api>stream stream>svc api>cdn svc>cdn', f:[['An engineer changes a rule; it is saved with an audit entry and broadcast.', 'eng>api:checkout-v2 → 5%|api>db|api>stream'], ['SDKs apply the change in memory; every check is a local function call.', 'stream>svc:rule update']]},
    points:[['Estimate', '<p>300 × 50K = 15M checks/s: impossible over the network, trivial in memory.</p>'], ['Stickiness', '<p>bucket = hash(flag_key + user_id) mod 100; enabled if bucket &lt; percentage, so increasing 5% → 10% keeps the first 5% on.</p>'], ['Resilience', '<p>SDKs start from a cached snapshot (CDN or disk) if the flag service is down; defaults are coded per flag.</p>'], ['Governance', '<p>Audit log, owners and expiry dates per flag; alert on stale flags.</p>']],
    tradeoffs:[['Local evaluation', 'Zero latency, works if the service is down', 'Rules (and user attributes) must be available in each service'], ['Streaming updates', 'Kill switch in seconds', 'Long-lived connections to manage']]},
  refs:['l:config-feature-flags', 'l:deploy-strategies']});

/* =========================== INTERMEDIATE =========================== */
C({id:'live-score', level:'intermediate', icon:'🏏', minutes:40, title:'Live cricket scores for 10 million fans', tagline:'One update every few seconds, to everyone at once.', tags:['fan-out', 'sse', 'cdn', 'pub/sub'],
  prompt:'A sports app shows live ball-by-ball scores. During an India–Pakistan match, 10M users have the score screen open. Each ball produces an update; users expect it within 2–3 seconds.',
  constraints:['10M concurrent viewers on one match; ~1 update every 30 s plus commentary', 'Updates within 3 s', 'Clients on flaky mobile networks', 'Cost matters: no per-user server work if avoidable'],
  hints:['Is the data different for each user? What does that imply for caching?', 'Compare 10M open WebSockets with 10M clients polling a cached file every 3 s.', 'Publish each update as a tiny JSON file on a CDN with a 1–2 s TTL and let clients poll it (or use SSE through a fan-out tier); the origin writes once per ball.'],
  solution:{summary:'Everyone sees the same score, so this is a broadcast problem, not a per-user one. Write each update once to an origin, and let a CDN absorb the reads (short-TTL polling or edge-pushed streams).',
    diagram:{n:[['fan', 'client', 'Fans ×10M', '', 0, 1], ['cdn', 'cdn', 'CDN edges', 'score.json · TTL 2 s', 1, 1], ['origin', 'service', 'Score origin', '', 2, 1], ['scorer', 'client', 'Official scorer', '', 4, 1], ['ingest', 'service', 'Ingest API', 'validates', 3, 1], ['db', 'db', 'Match DB', 'ball log', 3, 2]], e:'fan>cdn cdn>origin scorer>ingest ingest>db ingest>origin', f:[['The scorer records a ball; it is logged and a new score file is published.', 'scorer>ingest:4 runs|ingest>db|ingest>origin:score.json v812'], ['Clients poll the edge every 2–3 s; edges fetch from origin at most once per TTL.', 'fan>cdn:GET score.json|cdn>origin:once per 2 s']]},
    points:[['Estimate', '<p>Polling every 3 s: 10M ÷ 3 ≈ 3.3M requests/s at the edge, tiny 1 KB responses ≈ 27 Gbps, fine for a CDN; origin sees ~1 request per edge per TTL.</p>'], ['Push alternative', '<p>SSE/WebSockets cut latency and requests, but 10M connections need a large fan-out tier; many apps poll for scores and push only notifications.</p>'], ['Ordering', '<p>Each update carries a version; clients ignore older versions arriving late.</p>'], ['Notifications', '<p>Wickets and milestones go out as push notifications via topic subscriptions, rate-limited.</p>']],
    tradeoffs:[['Short-TTL polling via CDN', 'Simple, cheap, robust', 'A few seconds of delay; constant request volume'], ['Push (SSE)', 'Lower latency, fewer requests', 'Millions of open connections']]},
  refs:['l:cdn', 'l:realtime-transports', 'case:hotstar']});
C({id:'job-scheduler', level:'intermediate', icon:'⏰', minutes:45, title:'Distributed job scheduler (cron at scale)', tagline:'Run 10 million scheduled jobs, each exactly when due, even when machines die.', tags:['scheduling', 'leases', 'exactly-once', 'queues'],
  prompt:'Design a service where teams register jobs (“every day at 02:00 IST”, “in 30 minutes”, “every 5 minutes”) that call an HTTP endpoint or enqueue a message. Jobs must run on time and not twice.',
  constraints:['10M registered jobs; up to 50K due in the same second (e.g. midnight)', 'Fire within a few seconds of the due time', 'No job lost if a scheduler node dies', 'Jobs may take minutes; retries with backoff on failure'],
  hints:['How do you find which jobs are due right now without scanning 10M rows every second?', 'If two scheduler nodes both see a due job, how do you make sure only one runs it?', 'Index jobs by next_run_at, partition them across scheduler nodes, claim due jobs with a conditional update (or SELECT … FOR UPDATE SKIP LOCKED) with a lease, push them to a queue for workers, then compute and store the next run time.'],
  solution:{summary:'Store jobs with their next due time in a partitioned table; scheduler nodes poll their partitions for due jobs, claim each with a lease (so only one node fires it), hand it to a worker queue, and reschedule. Workers make execution idempotent.',
    diagram:{n:[['team', 'client', 'Team', 'registers job', 0, 1], ['api', 'service', 'Jobs API', '', 1, 1], ['db', 'db', 'Jobs DB', 'next_run_at index', 2, 1], ['sch', 'service', 'Schedulers', 'own partitions', 2, 0], ['q', 'queue', 'Run queue', '', 3, 0], ['w', 'service', 'Workers', 'retries', 4, 0], ['target', 'ext', 'Target endpoint', '', 4, 2]], e:'team>api api>db sch>db sch>q q>w w>target w>db', f:[['A team registers a job; its next_run_at is computed and stored.', 'team>api:every day 02:00 IST|api>db'], ['Each scheduler claims due jobs in its partitions with a lease and enqueues them.', 'sch>db:claim due (SKIP LOCKED)|sch>q:run #77'], ['A worker runs the job with an idempotency key and records the result.', 'q>w|w>target:POST (run id)|w>db:SUCCEEDED']]},
    points:[['Finding due jobs', '<p>Index on (partition, next_run_at); each poll fetches <code>WHERE next_run_at &lt;= now() LIMIT 1000</code>. A timing wheel in memory can hold the next few minutes for precision.</p>'], ['Exactly-once-ish', '<p>Claim with <code>UPDATE … SET lease_until = now()+60s WHERE id=? AND (lease_until IS NULL OR lease_until &lt; now())</code>; workers pass a run id as an idempotency key to targets.</p>'], ['Thundering midnight', '<p>50K jobs at 00:00: spread with optional jitter windows, and size the queue/workers for bursts.</p>'], ['Failure', '<p>If a scheduler dies, its partitions are reassigned (leases expire); jobs fire a few seconds late, not never.</p>'], ['Time zones', '<p>Store cron expression + time zone; compute next_run_at in UTC, handling DST.</p>']],
    tradeoffs:[['DB-backed with leases', 'Durable, simple to reason about', 'Polling load; seconds of precision'], ['At-least-once + idempotent targets', 'Robust to crashes', 'Targets must handle duplicates']]},
  refs:['l:distributed-locks', 'l:workflow-orchestration', 'l:delivery-semantics']});
C({id:'coupons', level:'intermediate', icon:'🎟️', minutes:35, title:'Promo codes with limited redemptions', tagline:'“First 10,000 orders get ₹200 off”: exactly 10,000.', tags:['atomic counters', 'idempotency', 'contention'],
  prompt:'Marketing creates promo codes like DIWALI200 with rules (min order, one per user, first N uses). During a sale, thousands of users apply the same code per second. Design redemption so limits are never exceeded.',
  constraints:['Up to 5,000 redemption attempts/s on one code', 'Hard global cap (e.g. 10,000) and one use per user', 'A redemption must be released if the order is cancelled or payment fails', 'Checkout must stay fast'],
  hints:['What breaks if you check “used &lt; 10,000” and then increment?', 'Where can you make the check-and-increment one atomic step, and how do you enforce one-per-user?', 'Reserve at checkout with an atomic script (Redis Lua or a conditional SQL update) that checks the cap and a per-user set, with a TTL; confirm on payment, release on failure/expiry; record redemptions in the database idempotently by order id.'],
  solution:{summary:'Treat a promo code like scarce inventory: reserve a redemption atomically at checkout (cap and per-user checks in one step), confirm when the order is paid, and release expired or failed reservations.',
    diagram:{n:[['u', 'client', 'Shopper', '', 0, 1], ['api', 'service', 'Checkout', '', 1, 1], ['gate', 'cache', 'Promo gate', 'Lua: cap + per-user', 2, 0], ['db', 'db', 'Redemptions DB', 'unique (code, user)', 2, 2], ['pay', 'service', 'Payments', '', 3, 1], ['sweep', 'service', 'Expiry sweeper', '', 3, 0]], e:'u>api api>gate api>db api>pay sweep>gate', f:[['Applying the code reserves one redemption atomically.', 'u>api:apply DIWALI200|api>gate:reserve (cap, user)'], ['Payment succeeds: the redemption is confirmed in the database, idempotent by order id.', 'api>pay|api>db:INSERT redemption'], ['Unpaid reservations expire and are returned.', 'sweep>gate:release expired']]},
    points:[['Atomic reserve', '<p>One Lua script: if user in set → reject; if used ≥ cap → reject; else INCR used, SADD user, store reservation with TTL.</p>'], ['Durability', '<p>The database row with a unique (code, user_id) constraint is the source of truth; the gate is rebuilt from it if lost.</p>'], ['Contention', '<p>One hot key is fine for Redis (100K+ ops/s); a relational row lock would serialise at a few thousand/s.</p>'], ['Abuse', '<p>One per user is weak against fake accounts: also limit per device, phone and payment instrument.</p>']],
    tradeoffs:[['Reserve then confirm', 'No over-redemption; failures release', 'Codes can look “used up” briefly while reservations expire'], ['In-memory gate', 'Fast under contention', 'Must reconcile with the database']]},
  refs:['l:locking', 'l:idempotency-rate-limit-headers', 'case:amazon']});
C({id:'nearby-friends', level:'intermediate', icon:'📍', minutes:40, title:'Nearby friends', tagline:'Who among my friends is within 2 km, updated every 30 seconds?', tags:['geospatial', 'pub/sub', 'presence', 'privacy'],
  prompt:'An opt-in feature shows which friends are within 2 km, with distances updated as people move. Users have up to 500 friends; 20M users have it enabled, 2M active at once.',
  constraints:['Location updates every 30 s from active users', 'Only friends who opted in; locations older than 10 min are hidden', 'Updates should appear within a few seconds', 'Battery and privacy matter'],
  hints:['Is this a “search everyone near me” problem, or only among my friends?', 'When my location changes, who needs to hear about it?', 'Keep each active user’s latest location in a cache with TTL; publish updates to a channel per user that active friends subscribe to through their WebSocket server; each receiver computes the distance and filters by 2 km.'],
  solution:{summary:'Because the candidate set is only friends, there’s no need for a global geo index: publish each user’s location to their own channel; online friends subscribed to it compute distances locally (or on their WebSocket server).',
    diagram:{n:[['a', 'client', 'Priya', 'moves', 0, 0], ['b', 'client', 'Rahul', 'friend', 0, 2], ['ws', 'service', 'WebSocket servers', '', 1, 1], ['loc', 'cache', 'Locations', 'TTL 10 min', 2, 0], ['ps', 'queue', 'Pub/sub', 'channel per user', 2, 2], ['graph', 'db', 'Friends DB', '', 3, 1]], e:'a>ws b>ws ws>loc ws>ps ws>graph', f:[['Priya’s app sends a location; it is cached and published to her channel.', 'a>ws:lat,lng|ws>loc:SET EX 600|ws>ps:publish loc:priya'], ['Rahul’s server is subscribed to his opted-in friends’ channels and forwards nearby ones.', 'ps>ws:Priya update|ws>b:Priya 1.2 km']]},
    points:[['Estimate', '<p>2M active ÷ 30 s ≈ 67K updates/s; each fans out to online friends (say 20 on average) ≈ 1.3M messages/s inside the pub/sub layer.</p>'], ['Subscriptions', '<p>On connect, load the friend list and subscribe to online, opted-in friends; unsubscribe on disconnect.</p>'], ['Distance', '<p>Haversine on the receiver side; only forward to the client when within 2 km or crossing the boundary.</p>'], ['Privacy', '<p>Coarsen locations, never store history, honour opt-out instantly by deleting the cache entry.</p>']],
    tradeoffs:[['Per-user channels', 'Work proportional to friends, not to everyone nearby', 'Large pub/sub fan-out'], ['Global geo index', 'Needed for “people nearby” (strangers)', 'Unnecessary for friends-only']]},
  refs:['l:geospatial', 'l:presence', 'l:websockets-at-scale']});
C({id:'metrics', level:'intermediate', icon:'📈', minutes:45, title:'Metrics ingestion and dashboards', tagline:'Ten million data points per second, queried by humans in milliseconds.', tags:['time series', 'downsampling', 'cardinality'],
  prompt:'Design a metrics system: services emit counters and gauges with labels every 10 s; engineers build dashboards and alerts over the last hour, day and year.',
  constraints:['10M samples/s; 50M active time series', 'Dashboards over 1 hour in &lt;1 s; over 1 year in &lt;5 s', 'Alerts evaluated every 30 s', 'Raw data kept 15 days, summaries for 2 years'],
  hints:['What makes time-series data compress so well, and how should you lay it out on disk?', 'Querying a year of 10-second points is billions of points. What should you precompute?', 'Shard by series id, append to in-memory chunks with delta-of-delta/XOR compression, flush to immutable blocks, downsample into 5-minute and 1-hour rollups, and guard against label cardinality explosions.'],
  solution:{summary:'Ingest through a stateless tier into shards keyed by series; store compressed time-ordered chunks; build rollups for long ranges; query by fanning out to shards and merging.',
    diagram:{n:[['svc', 'client', 'Services', 'emit metrics', 0, 1], ['ing', 'service', 'Ingesters', 'hash by series', 1, 1], ['wal', 'db', 'Hot blocks', 'compressed chunks', 2, 0], ['obj', 'db', 'Object storage', 'old blocks', 3, 0], ['roll', 'service', 'Downsampler', '5 min · 1 h', 3, 1], ['q', 'service', 'Query engine', 'fan-out + merge', 2, 2], ['ui', 'client', 'Dashboards', '', 4, 2]], e:'svc>ing ing>wal wal>obj obj>roll roll>obj~0.3 ui>q q>wal q>obj', f:[['Samples are routed by series id to an ingester, appended to compressed in-memory chunks, then flushed.', 'svc>ing:http_requests{svc,code}|ing>wal|wal>obj:2 h blocks'], ['A dashboard query fans out to recent blocks and rollups and merges results.', 'ui>q:rate(…[5m]) 30d|q>obj:1 h rollups|q>wal:last 2 h']]},
    points:[['Compression', '<p>Timestamps delta-of-delta encoded, values XOR-encoded (Gorilla): ~1.4 bytes per sample instead of 16.</p>'], ['Estimate', '<p>10M samples/s × 1.4 B ≈ 14 MB/s ≈ 1.2 TB/day raw; 15 days ≈ 18 TB; rollups are 30–360× smaller.</p>'], ['Cardinality', '<p>A label like user_id creates millions of series: enforce limits per metric and reject or drop offending labels.</p>'], ['Alerts', '<p>A rule evaluator queries recent data every 30 s; use burn-rate SLO alerts rather than raw thresholds.</p>']],
    tradeoffs:[['Rollups', 'Fast long-range queries', 'Lose detail (keep raw for recent data only)'], ['Pull vs push collection', 'Pull detects dead targets', 'Push suits short-lived jobs']]},
  refs:['l:time-series', 'l:golden-signals-red-use', 'l:alerting-oncall']});
C({id:'email-campaigns', level:'intermediate', icon:'📧', minutes:40, title:'Sending 100 million marketing emails', tagline:'Fast, polite to inbox providers, and never twice.', tags:['queues', 'throttling', 'idempotency', 'webhooks'],
  prompt:'A retailer sends a festive campaign to 100M subscribers. It must finish within 4 hours, respect each email provider’s rate limits, personalise every message, handle bounces and unsubscribes, and never send duplicates.',
  constraints:['100M recipients in 4 hours ≈ 7K emails/s', 'Gmail, Outlook etc. throttle senders that send too fast', 'Unsubscribes must apply immediately, even mid-campaign', 'Workers crash; the campaign must resume without duplicates'],
  hints:['Can one process loop over 100M rows? How would you split the work so it can resume?', 'Different receiving providers need different rates. How do you shape traffic per domain?', 'Split recipients into batches recorded in a table, process them via a queue, keep a sent-log keyed by (campaign, recipient) for idempotency, check suppression lists at send time, and use per-domain token buckets.'],
  solution:{summary:'Turn the campaign into many small, resumable batches; workers render and send with per-provider rate limits, check suppression lists at send time, and record each send idempotently. Bounces and complaints flow back as events.',
    diagram:{n:[['mkt', 'client', 'Marketer', '', 0, 1], ['plan', 'service', 'Campaign planner', 'creates batches', 1, 1], ['q', 'queue', 'Batch queue', '', 2, 1], ['w', 'service', 'Send workers', 'per-domain buckets', 3, 1], ['sup', 'cache', 'Suppression list', 'unsubscribes', 3, 0], ['log', 'db', 'Sent log', 'unique (campaign, user)', 3, 2], ['mta', 'ext', 'Email providers', '', 4, 1]], e:'mkt>plan plan>q q>w w>sup w>log w>mta mta>log~0.3', f:[['The planner splits recipients into 100K batches of 1,000.', 'mkt>plan:launch|plan>q:batches'], ['A worker checks suppression, renders, sends within the domain’s rate, and records the send.', 'q>w|w>sup:skip unsubscribed|w>mta:SMTP|w>log:sent'], ['Bounces and complaints update the logs and suppression list.', 'mta>log:bounce webhook']]},
    points:[['Idempotency', '<p>Before sending, insert (campaign_id, recipient_id) into the sent log; a duplicate key means skip. Crash-resumed batches then can’t double-send.</p>'], ['Throttling', '<p>Token bucket per recipient domain and per sending IP; back off on 4xx deferrals.</p>'], ['Freshness', '<p>Check the suppression list at send time, not when batches were created.</p>'], ['Deliverability', '<p>SPF/DKIM/DMARC, warmed IPs, list hygiene: these matter as much as throughput.</p>']],
    tradeoffs:[['Batches in a queue', 'Parallel, resumable', 'Ordering across batches not guaranteed'], ['Sent-log check per email', 'No duplicates', 'An extra write per email']]},
  refs:['l:backpressure', 'l:idempotency-rate-limit-headers', 'case:notification-service']});
C({id:'price-alerts', level:'intermediate', icon:'📉', minutes:40, title:'Stock price alerts', tagline:'Notify 5 million users when a price crosses their threshold.', tags:['streams', 'indexing', 'fan-out'],
  prompt:'Users set alerts like “tell me when INFY drops below ₹1,400”. Prices for 5,000 stocks tick several times a second during market hours. Design the alerting system.',
  constraints:['20M active alerts on 5,000 symbols', '50K price ticks/s', 'Notify within 2 s of the crossing', 'Each alert fires once (then the user re-arms it)'],
  hints:['For each tick, could you check all 20M alerts? What smaller set needs checking?', 'For one symbol, alerts are thresholds. How would you find all thresholds crossed between the previous and the new price?', 'Partition alerts by symbol; keep, per symbol, a sorted structure of thresholds (above/below); on each tick, range-query thresholds between old and new price, fire them, and remove them atomically; push notifications through a queue.'],
  solution:{summary:'Partition by symbol and index thresholds in sorted order, so each tick only touches alerts in the price range it just crossed.',
    diagram:{n:[['feed', 'ext', 'Exchange feed', 'ticks', 0, 1, 120], ['part', 'queue', 'Ticks by symbol', 'partitioned', 1, 1], ['eval', 'service', 'Evaluators', 'sorted thresholds', 2, 1], ['adb', 'db', 'Alerts DB', '', 2, 2], ['nq', 'queue', 'Notify queue', '', 3, 1], ['push', 'ext', 'Push / SMS', '', 4, 1], ['u', 'client', 'User', 'creates alert', 1, 2]], e:'feed>part part>eval eval>adb eval>nq nq>push u>adb', f:[['A tick for INFY reaches the evaluator that owns INFY.', 'feed>part:INFY 1,398|part>eval'], ['It range-queries thresholds between the previous and new price, marks them fired, and queues notifications.', 'eval>adb:fired 1,212 alerts|eval>nq|nq>push']]},
    points:[['Index', '<p>Per symbol: two sorted sets (below-thresholds, above-thresholds). A drop from 1,412 to 1,398 fires all “below” alerts with threshold in [1,398, 1,412).</p>'], ['Estimate', '<p>Most ticks cross no thresholds; work is proportional to alerts fired, not alerts stored.</p>'], ['Exactly once', '<p>Remove the alert from the index and mark it fired in one transaction before notifying; notifications are idempotent by alert id.</p>'], ['Hot symbols', '<p>A crash in a popular stock fires millions at once: the notify queue absorbs the burst.</p>']],
    tradeoffs:[['Partition by symbol', 'Ordered ticks per symbol, local indexes', 'Hot symbols concentrate load'], ['In-memory indexes', 'Microsecond range queries', 'Rebuilt from the database on restart']]},
  refs:['l:batch-vs-stream', 'l:kafka', 'l:fan-out']});
C({id:'trending', level:'intermediate', icon:'🔥', minutes:40, title:'Top-K trending hashtags', tagline:'What is trending in the last hour, updated every minute?', tags:['streaming', 'count-min sketch', 'sliding windows', 'top-k'],
  prompt:'Show the top 10 trending hashtags globally and per city over the last hour, refreshed every minute, from a stream of 500K posts per second.',
  constraints:['500K posts/s, ~2 hashtags each', 'Millions of distinct hashtags', 'Top 10 per city for 2,000 cities', 'Approximate counts are fine; freshness within a minute'],
  hints:['Can you keep an exact counter for every hashtag in every city and window?', 'Which probabilistic structure counts frequencies in fixed memory, and how do you get top-K from it?', 'Use minute buckets with a count-min sketch + a min-heap of candidates per region, merge the last 60 buckets for the hour, partition the stream by hashtag (or by region) and combine partial top-Ks.'],
  solution:{summary:'Count in fixed memory with count-min sketches per minute bucket, keep a small heap of heavy hitters, and slide a 60-minute window by merging buckets. Partition the work and merge partial top-K lists.',
    diagram:{n:[['posts', 'client', 'Posts stream', '', 0, 1], ['k', 'queue', 'Kafka', 'by hashtag', 1, 1], ['agg', 'service', 'Stream counters', 'CMS + heap / minute', 2, 1], ['merge', 'service', 'Top-K merger', 'last 60 min', 3, 1], ['cache', 'cache', 'Trending cache', 'global + city', 4, 1], ['app', 'client', 'App', '', 4, 2]], e:'posts>k k>agg agg>merge merge>cache app>cache', f:[['Hashtags are partitioned and counted per minute in sketches with candidate heaps.', 'posts>k:#IPLFinal|k>agg'], ['Every minute, partial top-Ks for the last hour are merged and published.', 'agg>merge:partial top-K|merge>cache:top 10'], ['Apps read the cached lists.', 'app>cache']]},
    points:[['Count-min sketch', '<p>A width × depth grid of counters; estimates never under-count; error ≈ total/width with probability set by depth.</p>'], ['Trending, not popular', '<p>Rank by growth: current hour vs the same hour baseline (z-score), or #IPL is always on top.</p>'], ['Partitioning', '<p>Partition by hashtag for exact-ish counts; per-city lists are computed from region-tagged events.</p>'], ['Abuse', '<p>Filter bot accounts and coordinated spam before counting.</p>']],
    tradeoffs:[['Sketches', 'Fixed memory regardless of distinct tags', 'Approximate counts'], ['Minute buckets', 'Simple sliding window', '1-minute granularity']]},
  refs:['l:hll-cms', 'l:batch-vs-stream', 'pg:bloom']});
C({id:'edtech-video', level:'intermediate', icon:'🎓', minutes:40, title:'Video pipeline for an ed-tech platform', tagline:'Teachers upload lectures; students stream them on 3G.', tags:['transcoding', 'workflows', 'abr', 'drm'],
  prompt:'Teachers upload 1–3 hour lecture recordings. Each must become an adaptive stream (360p–1080p), get auto-generated captions, a thumbnail and chapter markers, and be playable only by enrolled students.',
  constraints:['5,000 hours uploaded per day', 'Students mostly on mobile data in small towns', 'Paid content: prevent casual downloading and link sharing', 'Processing within 1 hour of upload'],
  hints:['A 3-hour file is huge. How do you make transcoding fast and resumable?', 'Several steps can run in parallel. How would you coordinate them and retry failures?', 'Resumable chunked upload → split into segments → parallel transcode into an ABR ladder → package HLS with encryption keys → captions via speech-to-text in parallel → workflow engine tracks the DAG → CDN with signed URLs and a licence/key server checking enrolment.'],
  solution:{summary:'Treat processing as a workflow (DAG) of idempotent tasks: split, transcode segments in parallel, package with encryption, and run captions and thumbnails alongside. Deliver via CDN with short-lived signed URLs and keys gated on enrolment.',
    diagram:{n:[['t', 'client', 'Teacher', 'upload', 0, 0], ['s', 'client', 'Student', '', 0, 2], ['up', 'service', 'Upload service', 'resumable', 1, 0], ['wf', 'service', 'Workflow engine', 'DAG + retries', 2, 1], ['tx', 'service', 'Transcoders', 'segments ×N', 3, 0], ['cap', 'service', 'Captions', 'speech-to-text', 3, 2], ['st', 'db', 'Storage', 'HLS + keys', 4, 1], ['cdn', 'cdn', 'CDN', 'signed URLs', 1, 2]], e:'t>up up>wf wf>tx wf>cap tx>st cap>st s>cdn cdn>st~0.1', f:[['The upload completes and starts a workflow.', 't>up:chunked upload|up>wf:new lecture'], ['Segments transcode in parallel while captions run alongside.', 'wf>tx:split + ladder|wf>cap|tx>st:HLS (AES)|cap>st:VTT'], ['An enrolled student gets signed URLs and streams adaptively.', 's>cdn:playlist + segments|cdn>st']]},
    points:[['Estimate', '<p>5,000 h/day × 4 renditions; with segment-parallel encoding, a 3-hour lecture finishes in minutes on a pool of a few hundred cores.</p>'], ['Bitrates', '<p>Lectures are mostly static slides: low bitrates (150–800 kbps) look fine; add an audio-only rendition for very weak networks.</p>'], ['Protection', '<p>HLS AES-128 or DRM; key requests authenticated against enrolment; URLs signed and short-lived; watermark the user id to discourage leaks.</p>'], ['Workflow', '<p>Each task idempotent and retried; the engine records state so a crashed run resumes rather than restarts.</p>']],
    tradeoffs:[['Segment-parallel transcoding', 'Fast turnaround', 'More orchestration'], ['DRM vs AES + signed URLs', 'DRM is stronger', 'Costs and device support']]},
  refs:['l:transcoding-pipeline', 'l:live-streaming-abr', 'l:workflow-orchestration', 'case:youtube']});
C({id:'api-gateway', level:'intermediate', icon:'🚪', minutes:40, title:'API gateway with auth and quotas', tagline:'One front door for 200 services and 10,000 partner apps.', tags:['gateway', 'auth', 'rate limiting', 'routing'],
  prompt:'A company exposes public APIs to 10,000 partner apps. Design a gateway that authenticates API keys and OAuth tokens, enforces per-plan quotas, routes to 200 internal services, and logs usage for billing.',
  constraints:['200K requests/s at peak', 'Gateway adds &lt;5 ms p99', 'Quotas per partner per minute and per month', 'Usage must be billable (no lost or double-counted calls)'],
  hints:['Which checks can be done locally on the gateway node, and which need shared state?', 'A per-minute quota across 50 gateway nodes: how do you count without a network call on every request?', 'Validate JWTs locally with cached keys, look up API keys in a local cache, enforce quotas with local token buckets synced to Redis in small batches, route via a service registry, and send usage events to a log for billing aggregation.'],
  solution:{summary:'Keep the hot path local: cached credentials, local token buckets periodically reconciled with a shared store, and a routing table from service discovery. Usage goes asynchronously to an event log for exact billing.',
    diagram:{n:[['p', 'client', 'Partner app', '', 0, 1], ['gw', 'lb', 'Gateway nodes', 'auth · quotas · routing', 1, 1], ['redis', 'cache', 'Quota store', 'Redis', 2, 0], ['reg', 'service', 'Service registry', '', 2, 2], ['svc', 'service', 'Internal services', '×200', 3, 1], ['log', 'queue', 'Usage log', 'Kafka', 3, 0], ['bill', 'service', 'Billing', 'aggregates', 4, 0]], e:'p>gw gw>redis gw>reg gw>svc gw>log log>bill', f:[['The gateway authenticates locally and checks its local token bucket.', 'p>gw:GET /v2/orders (key)|gw>redis:sync usage every 100 ms'], ['It routes to a healthy instance and emits a usage event.', 'gw>reg:orders → instances|gw>svc|gw>log:usage event'], ['Billing aggregates usage per partner per month.', 'log>bill']]},
    points:[['Latency budget', '<p>No synchronous remote call for most requests: JWT verification and cached key lookups are microseconds.</p>'], ['Distributed quotas', '<p>Each node takes a share of the quota or syncs counts every ~100 ms; allow small overshoot, or use a central Redis bucket for strict per-second limits.</p>'], ['Billing accuracy', '<p>Usage events carry a request id; the aggregator deduplicates. Monthly quotas read from the aggregated counts.</p>'], ['Resilience', '<p>If Redis is down, fall back to local-only limits; never let the quota store take the API down.</p>']],
    tradeoffs:[['Local approximate quotas', 'Tiny latency', 'Brief overshoot across nodes'], ['Async usage logging', 'Off the hot path', 'Billing lags by minutes']]},
  refs:['l:proxies-gateway-bff', 'l:rate-limiting', 'l:api-keys-mtls', 'case:rate-limiter']});
C({id:'whiteboard', level:'intermediate', icon:'🖍️', minutes:45, title:'Collaborative whiteboard', tagline:'Twenty people drawing on one canvas, offline edits included.', tags:['crdt', 'websockets', 'sync', 'snapshots'],
  prompt:'Design a shared whiteboard (sticky notes, shapes, arrows, freehand). Up to 50 people edit one board at once, see each other’s cursors, and can keep working briefly offline.',
  constraints:['50 concurrent editors per board; 100K active boards', 'Changes visible to others in &lt;200 ms', 'Offline edits merge on reconnect', 'Boards with 10K objects must open quickly'],
  hints:['Two people move the same sticky note at once. What should happen?', 'Do you need character-level operational transformation here, or something simpler per object?', 'Model the board as a map of objects with per-property last-writer-wins (a CRDT-style register), sync ops over WebSocket through a per-board session, persist an op log plus snapshots, and send cursors as ephemeral presence.'],
  solution:{summary:'Objects are independent, so conflicts are per property: use last-writer-wins registers with logical timestamps (a simple CRDT), relay ops through a per-board session server, and persist snapshots plus recent ops.',
    diagram:{n:[['a', 'client', 'Editor A', '', 0, 0], ['b', 'client', 'Editor B', '', 0, 2], ['gw', 'service', 'WebSocket gateway', '', 1, 1], ['sess', 'service', 'Board session', 'one owner per board', 2, 1], ['log', 'db', 'Op log', '', 3, 0], ['snap', 'db', 'Snapshots', '', 3, 2]], e:'a>gw b>gw gw>sess sess>log sess>snap', f:[['A moves a note; the op carries a logical timestamp and goes to the board’s session.', 'a>gw:note 17 x=420 @(lamport 812, A)|gw>sess'], ['The session persists and broadcasts it; each client merges with last-writer-wins per property.', 'sess>log|sess>gw|gw>b'], ['Snapshots let large boards open fast.', 'sess>snap:every 1,000 ops']]},
    points:[['Conflicts', '<p>Per object property: highest (Lamport time, client id) wins. Deleting wins over moving via a tombstone.</p>'], ['Freehand', '<p>A stroke is an append-only object; created once, rarely edited, so no conflicts.</p>'], ['Offline', '<p>Queue ops locally with timestamps; on reconnect send them and merge; LWW guarantees convergence.</p>'], ['Scale', '<p>Route each board to one session server by hash; large boards load a snapshot then recent ops.</p>']],
    tradeoffs:[['LWW per property', 'Simple, always converges', 'Concurrent edits to the same property lose one'], ['Session per board', 'Ordering and fan-out in one place', 'Hot boards limited by one server']]},
  refs:['l:crdts-merkle', 'l:offline-first-sync', 'case:google-docs', 'pg:vector-clock']});
})();
